      const tw = Math.min(...toe.map((r) => Math.abs(insideSec(F, r, 0.03)[0][2]) / 0.95));
      put('trim', loft(toe.map((r) => r.map(([x, y, z]) => [x, y, z * tw])), C.carpet, { closed: false, caps: false }));
