          const t = (x + 0.14) / 0.54, yc = -0.1 + 0.065 * t, hb = 0.05 + 0.03 * Math.sin(t * Math.PI), pr = uProf(0.52, 0.3, hb, 0.09);
          const sq = j === 0 ? 0.82 : j === 1 ? 0.95 : 1, sh = j === 0 ? 0.35 : j === 1 ? 0.8 : 1;
